public static int min(int[] arr) {
    int min = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

public static int indexOfMin(int[] arr) {
    int index = 0;
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < arr[index]) {
            index = i;
        }
    }
    return index;
}

